def revise_docx(source: Path, target: Path) -> None:
    doc = Document(str(source))
    paragraphs = doc.paragraphs
    for index, text in REPLACEMENTS.items():
        if index >= len(paragraphs):
            raise IndexError(f"Paragraph index {index} out of range; total={len(paragraphs)}")
        paragraphs[index].text = text
    doc.save(str(target))


def main() -> int:
    if len(sys.argv) not in {2, 3}:
        print("Usage: revise_thesis_focus.py <source.docx> [target.docx]")
        return 1

    source = Path(sys.argv[1])
    if len(sys.argv) == 3:
        target = Path(sys.argv[2])
    else:
        target = source.with_name(source.stem + "-聚焦核心模块修订版.docx")

    revise_docx(source, target)
    print(target)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
